  "type": "object",
  "properties": {
    "name": {
      "type": "string"
    },
    "model": {
      "type": "string"
    },
    "year": {
      "type": "integer"
    },
    "status": {
      "type": "string",
      "enum": ["active", "inactive"]
    },
    "placeholders": {
      "type": "array",
      "items": {
        "type": "string",
